def compute(vars):
    initial_value = vars["v1"]
    ending_value = vars["v2"]

    if initial_value == 0:
        return None

    roi = (ending_value - initial_value) / initial_value

    return {
        "value": roi,
        "trace": {
            "initial_value": initial_value,
            "ending_value": ending_value,
            "change": ending_value - initial_value,
            "roi": roi,
            "output_meta": {
                "currency": None,
                "scale": None,
                "unit": "ratio"
            }
        }
    }
